type NodeMetrics = {
  name: string;
  status: "Ready";
  cpu: number;
  mem: number;
  temp: number;
};

const initialNodes: NodeMetrics[] = [
  { name: "node-01", status: "Ready", cpu: 14, mem: 41, temp: 48 },
  { name: "node-02", status: "Ready", cpu: 9, mem: 38, temp: 45 },
];

const drift = (v: number, range: number, min: number, max: number) => {
  const next = v + (Math.random() - 0.5) * range;
  return Math.max(min, Math.min(max, next));
};

const KubectlTop = () => {
  const [nodes, setNodes] = useState(initialNodes);

  useEffect(() => {
    const id = setInterval(() => {
      setNodes((ns) =>
        ns.map((n) => ({
          ...n,
          cpu: drift(n.cpu, 8, 2, 92),
          mem: drift(n.mem, 2, 25, 78),
          temp: drift(n.temp, 1.5, 42, 64),
        })),
      );
    }, 1500);
    return () => clearInterval(id);
  }, []);

  const bar = (v: number) => {
    const blocks = 10;
    const filled = Math.round((v / 100) * blocks);
    return (
      <span className="text-muted-foreground">
        <span className="text-emerald-400">{"█".repeat(filled)}</span>
        {"░".repeat(blocks - filled)}
      </span>
    );
  };

  return (
    <div className="text-sm">
      <div className="grid grid-cols-[6rem_5rem_10rem_10rem_4rem] gap-x-5 text-muted-foreground">
        <span>NAME</span>
        <span>STATUS</span>
        <span>CPU</span>
        <span>MEM</span>
        <span>TEMP</span>
      </div>
      {nodes.map((n) => (
        <div
          key={n.name}
          className="grid grid-cols-[6rem_5rem_10rem_10rem_4rem] gap-x-5 tabular-nums items-baseline"
        >
          <span className="text-foreground">{n.name}</span>
          <span className="text-emerald-400 whitespace-nowrap">
            ● {n.status}
          </span>
          <span className="whitespace-nowrap">
            {bar(n.cpu)}
            <span className="text-foreground ml-2">
              {n.cpu.toFixed(0).padStart(2, " ")}%
            </span>
          </span>
          <span className="whitespace-nowrap">
            {bar(n.mem)}
            <span className="text-foreground ml-2">
              {n.mem.toFixed(0).padStart(2, " ")}%
            </span>
          </span>
          <span className="text-foreground">{n.temp.toFixed(0)}°C</span>
        </div>
      ))}
      <div className="mt-1 text-xs text-muted-foreground">
        k3s · 2× raspberry pi 5 · arm64 · bare-metal
      </div>
    </div>
  );
};

