const runCommand = (raw: string): Line[] => {
  const cmd = raw.trim();
  if (cmd === "") return [{ kind: "prompt", cmd: "" }];

  const base: Line[] = [{ kind: "prompt", cmd }];

  switch (cmd) {
    case "whoami":
      return [...base, { kind: "out", node: <Whoami /> }, { kind: "spacer" }];
    case "links":
    case "ls links":
    case "ls links/":
      return [...base, { kind: "out", node: <Links /> }, { kind: "spacer" }];
    case "kubectl top nodes":
    case "top":
      return [
        ...base,
        { kind: "out", node: <KubectlTop /> },
        { kind: "spacer" },
      ];
    case "uname -a":
    case "uname":
      return [...base, { kind: "out", node: <Uname /> }, { kind: "spacer" }];
    case "help":
    case "?":
      return [...base, { kind: "out", node: <HelpOutput /> }, { kind: "spacer" }];
    case "clear":
      return [];
    default:
      return [
        ...base,
        {
          kind: "out",
          node: (
            <span className="text-muted-foreground">
              {cmd.split(" ")[0]}: command not found. try{" "}
              <span className="text-cyan-400">help</span>.
            </span>
          ),
        },
        { kind: "spacer" },
      ];
  }
};

const BOOT_SCRIPT: { cmd: string; delay: number }[] = [
  { cmd: "whoami", delay: 350 },
  { cmd: "ls links/", delay: 700 },
  { cmd: "kubectl top nodes", delay: 900 },
];

export const Terminal = () => {
  const [lines, setLines] = useState<Line[]>([]);
  const [input, setInput] = useState("");
  const [booted, setBooted] = useState(false);
  const [history, setHistory] = useState<string[]>([]);
  const [histIdx, setHistIdx] = useState<number | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // boot sequence
  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      for (const step of BOOT_SCRIPT) {
        await new Promise((r) => setTimeout(r, step.delay));
        if (cancelled) return;
        setLines((prev) => [...prev, ...runCommand(step.cmd)]);
      }
      if (!cancelled) setBooted(true);
    };
    run();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [lines]);

  const focus = useCallback(() => inputRef.current?.focus(), []);

  useEffect(() => {
    if (booted) focus();
  }, [booted, focus]);

  const onKey = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      const cmd = input;
      setLines((prev) => [...prev, ...runCommand(cmd)]);
      if (cmd.trim()) setHistory((h) => [...h, cmd]);
      setInput("");
      setHistIdx(null);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      if (history.length === 0) return;
      const next = histIdx === null ? history.length - 1 : Math.max(0, histIdx - 1);
      setHistIdx(next);
      setInput(history[next]);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      if (histIdx === null) return;
      const next = histIdx + 1;
      if (next >= history.length) {
        setHistIdx(null);
        setInput("");
      } else {
        setHistIdx(next);
        setInput(history[next]);
      }
    } else if (e.key === "l" && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      setLines([]);
    }
  };

  return (
    <div
      onClick={focus}
      className="w-full max-w-3xl rounded-lg border border-border bg-black/40 backdrop-blur-sm shadow-2xl overflow-hidden flex flex-col"
    >
      {/* title bar */}
      <div className="flex items-center gap-2 px-3 py-2 border-b border-border bg-white/[0.02]">
        <span className="size-3 rounded-full bg-red-500/70" />
        <span className="size-3 rounded-full bg-yellow-500/70" />
        <span className="size-3 rounded-full bg-emerald-500/70" />
        <span className="ml-2 text-xs text-muted-foreground">
          {USER}@{HOST}: ~ — zsh
        </span>
      </div>

      {/* body */}
      <div
        ref={scrollRef}
        className="px-4 py-4 text-sm leading-relaxed font-mono h-[60vh] md:h-[28rem] overflow-y-auto"
      >
        {lines.map((l, i) => {
          if (l.kind === "prompt") return <Prompt key={i} cmd={l.cmd} />;
          if (l.kind === "spacer") return <div key={i} className="h-2" />;
          return (
            <div key={i} className="my-1">
              {l.node}
            </div>
          );
        })}

        {/* live prompt */}
        {booted && (
          <div className="flex flex-wrap gap-x-1.5 items-center">
            <span className="text-emerald-400">
              {USER}@{HOST}
            </span>
            <span className="text-muted-foreground">:</span>
            <span className="text-cyan-400">{CWD}</span>
            <span className="text-muted-foreground">$</span>
            <div className="relative flex-1 min-w-[10ch]">
              <input
                ref={inputRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={onKey}
                spellCheck={false}
                autoCapitalize="off"
                autoCorrect="off"
                className="absolute inset-0 w-full bg-transparent outline-none text-foreground caret-emerald-400"
                aria-label="terminal input"
              />
              <span className="invisible whitespace-pre">
                {input || " "}
              </span>
            </div>
          </div>
        )}
      </div>

      {/* hint footer */}
      <div className="px-4 py-2 border-t border-border text-xs text-muted-foreground bg-white/[0.02]">
        try{" "}
        <span className="text-cyan-400">help</span>,{" "}
        <span className="text-cyan-400">kubectl top nodes</span>,{" "}
        <span className="text-cyan-400">links</span>
      </div>
    </div>
  );
};
